"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

import { HandedOverPassword } from "@/components/admin/HandedOverPassword";
import { Field } from "@/components/auth/Field";
import { useStepUp } from "@/components/auth/useStepUp";
import type { HandedOver } from "@/lib/api";
import { apiPost } from "@/lib/browser-api";
import type { FormError } from "@/lib/errors";

/**
 * Appoints a moderator: an address, and nothing else to fill in.
 *
 * The password is generated by the platform rather than typed here — one a person invents
 * while creating the sixth moderator this month is one weak password, or one password used
 * six times. It comes back once, and this screen is the only place it is ever readable.
 *
 * Temporary either way: the moderator cannot use the platform until they replace it, which is
 * what makes it safe to send in a chat message.
 */
export function AppointModerator() {
  const router = useRouter();
  const { attempt, prompt } = useStepUp();
  const [appointed, setAppointed] = useState<HandedOver | null>(null);
  const [error, setError] = useState<FormError | null>(null);
  const [pending, setPending] = useState(false);

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setError(null);
    setAppointed(null);
    const form = event.currentTarget;
    const body = { email: new FormData(form).get("email") };
    const result = await attempt(() => apiPost<HandedOver>("/admin/moderators", body));
    setPending(false);
    if (!result.ok) {
      setError(result.error);
      return;
    }
    setAppointed(result.data);
    form.reset();
    router.refresh();
  }

  return (
    <section className="flex flex-col gap-3 rounded-card border border-ink-muted/20 p-4">
      <h2 className="font-medium">Завести модератора</h2>
      <p className="text-sm text-ink-muted">
        Нужен только адрес. Пароль площадка придумает сама и покажет один раз — передайте его
        человеку сами.
      </p>
      <form onSubmit={onSubmit} className="flex flex-col gap-3" noValidate>
        <div className="flex flex-wrap items-end gap-2">
          <div className="min-w-64 flex-1">
            <Field
              label="Email"
              name="email"
              type="email"
              autoComplete="off"
              error={error?.fieldErrors["email"]}
            />
          </div>
          <button
            type="submit"
            disabled={pending}
            className="rounded-lg bg-brand px-4 py-2 font-medium text-white disabled:opacity-60"
          >
            {pending ? "Заводим…" : "Завести"}
          </button>
        </div>
        {error && Object.keys(error.fieldErrors).length === 0 ? (
          <p role="alert" className="text-sm text-danger">
            {error.message}
          </p>
        ) : null}
      </form>

      {prompt}

      {appointed === null ? null : (
        <HandedOverPassword email={appointed.user.email} password={appointed.password} />
      )}
    </section>
  );
}
